import { PutItemCommand } from 'dynamodb-toolbox/entity/actions/put';
import { ScanCommand } from 'dynamodb-toolbox/table/actions/scan';
import { MODELO_PIEZA, MODELO_MUSEO, TABLA_PIEZAS } from '../../models/museo-pieza.model.mjs';

export async function crearPiezaRepository(pieza) {
  await MODELO_PIEZA.build(PutItemCommand)
    .item(pieza)
    .options({ condition: { attr: 'piezaId', exists: false } })
    .send();
}

export async function listarPiezasRepository() {
  const { Items = [] } = await TABLA_PIEZAS.build(ScanCommand)
    .entities(MODELO_PIEZA)
    .options({ consistent: true })
    .send();
  return Items;
}

