export async function buscarMuseoRepository(museoId) {
  const { Item } = await MODELO_MUSEO.build(GetItemCommand)
    .key({ museoId }).options({ consistent: true }).send();
  return Item ?? null;
}

export async function consultarMuseoRepository(museoId, minimo) {
  const { Items = [] } = await TABLA_PIEZAS.build(QueryCommand)
    .entities(MODELO_PIEZA)
    .query({ index: 'PorMuseo', partition: museoId })
    .options({ filters: { Pieza: { attr: 'antiguedadAnios', gte: minimo } } })
    .send();
  return Items;
}

import { trasladarPiezaService } from './service.mjs';

export async function handler(event) {
  const piezaId = Number(event.pathParameters.piezaId);
  const { museoId } = JSON.parse(event.body);
  const resultado = await trasladarPiezaService(piezaId, museoId);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { trasladarPiezaRepository } from './repository.mjs';
import { buscarMuseoRepository } from '../../museos/consultar/repository.mjs';

export async function trasladarPiezaService(piezaId, museoId) {
  const museo = await buscarMuseoRepository(museoId);
  if (!museo) throw new Error('Museo no encontrado');
  return trasladarPiezaRepository(piezaId, museoId);
}

import { UpdateItemCommand } from 'dynamodb-toolbox/entity/actions/update';
import { MODELO_PIEZA, MODELO_MUSEO, TABLA_PIEZAS } from '../../models/museo-pieza.model.mjs';

export async function trasladarPiezaRepository(piezaId, museoId) {
  const { Attributes } = await MODELO_PIEZA.build(UpdateItemCommand)
    .item({ piezaId, museoId })
    .options({
      condition: { attr: 'piezaId', exists: true },
      returnValues: 'ALL_NEW'
    })
    .send();
  return Attributes;
}

import { consultarMuseoService } from './service.mjs';

export async function handler(event) {
  const museoId = Number(event.pathParameters.museoId);
  const minimo = Number(event.queryStringParameters?.minimo ?? 0);
  const resultado = await consultarMuseoService(museoId, minimo);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { buscarMuseoRepository, consultarMuseoRepository } from './repository.mjs';

export async function consultarMuseoService(museoId, minimo) {
  const museo = await buscarMuseoRepository(museoId);
  if (!museo) throw new Error('Museo no encontrado');
  const piezas = await consultarMuseoRepository(museoId, minimo);
  return { museo, piezas };
}

